59:   function drawPond(){const x=1930,y=1900,p=worldToScreen(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#8ccdc1';ctx.beginPath();ctx.ellipse(0,0,132,90,-.22,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d4e3a9';ctx.lineWidth=12;ctx.stroke();ctx.fillStyle='#b1e1cf';ctx.beginPath();ctx.ellipse(-8,-5,108,68,-.22,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e6f4d0aa';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(8,-7,77,43,-.22,0,Math.PI*2);ctx.stroke();for(const [lx,ly] of [[-60,-20],[66,28],[20,-47]]){ctx.fillStyle='#77ad78';ctx.beginPath();ctx.ellipse(lx,ly,12,6,.45,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(lx+3,ly-2,3,Math.PI,0);ctx.fill()}ctx.restore()}
